import 'dart:ui';

/// Exact TrueType vector outlines extracted directly from iconsax.ttf
/// (unitsPerEm = 1024, ascent = 960, descent = -64).
/// Rendering these via CustomPaint bypasses Android HarfBuzz text shaping
/// bugs on Unicode Combining Marks (0x0300..0x036F), Hebrew (0x0590..0x05FF),
/// and Arabic (0x0600..0x06FF) codepoints used by package:iconsax.
bool hasIconsaxSolidPath(int codePoint) => _rawGlyphData.containsKey(codePoint);

Path? buildIconsaxSolidPath(int codePoint, Size size) {
  final raw = _rawGlyphData[codePoint];
  if (raw == null) return null;
  final path = Path()..fillType = PathFillType.evenOdd;
  final sx = size.width / 1024.0;
  final sy = size.height / 1024.0;
  int i = 0;
  while (i < raw.length) {
    final cmd = raw[i++];
    if (cmd == 0) {
      final x = raw[i++] * sx;
      final y = (960.0 - raw[i++]) * sy;
      path.moveTo(x, y);
    } else if (cmd == 1) {
      final x = raw[i++] * sx;
      final y = (960.0 - raw[i++]) * sy;
      path.lineTo(x, y);
    } else if (cmd == 2) {
      final cx = raw[i++] * sx;
      final cy = (960.0 - raw[i++]) * sy;
      final x = raw[i++] * sx;
      final y = (960.0 - raw[i++]) * sy;
      path.quadraticBezierTo(cx, cy, x, y);
    } else if (cmd == 3) {
      path.close();
    }
  }
  return path;
}

